**Root cause (GAP-019 / tick 106):** The DELETE handler for `DELETE /v1/sessions/{id}` called `store.delete()` unconditionally and returned `200 OK` even when the id wasn't a tracked session, while `GET /v1/sessions/{id}` and `POST /v1/sessions/{id}/cancel` both returned `404`. The three verbs validated session existence through different code paths, so behavior drifted.

**The fix:** Route all three verbs through one shared existence gate — a `require_tracked_session` dependency that resolves the session (or raises `404`) before the handler runs. DELETE now 404s unknown tracked sessions instead of silently succeeding.

**Before (buggy):**
```python
@router.delete("/v1/sessions/{session_id}", response_model=DeleteOut)
def delete_session(session_id: str) -> DeleteOut:
    store.delete(session_id)          # BUG: no existence check — unknown ids return 200
    return DeleteOut(status="deleted")
```

**After (fixed, tick 106):**
```python
from fastapi import APIRouter, Depends, HTTPException

def require_tracked_session(session_id: str) -> Session:
    """Shared existence gate — single source of truth for session validation."""
    session = store.get(session_id)
    if session is None:
        raise HTTPException(status_code=404, detail=f"session '{session_id}' not found")
    return session

@router.get("/v1/sessions/{session_id}", response_model=SessionOut)
def get_session(session: Session = Depends(require_tracked_session)) -> SessionOut:
    return SessionOut(id=session.id, state=session.state)

@router.post("/v1/sessions/{session_id}/cancel", response_model=SessionOut)
def cancel_session(session: Session = Depends(require_tracked_session)) -> SessionOut:
    store.cancel(session.id)
    return SessionOut(id=session.id, state="cancelled")

@router.delete("/v1/sessions/{session_id}", response_model=DeleteOut)
def delete_session(session: Session = Depends(require_tracked_session)) -> DeleteOut:
    # Fix: existence validated above; unknown ids never reach the handler.
    store.delete(session.id)
    return DeleteOut(status="deleted")
```

**Regression tests added (2 new at tick 106, in `tests/test_delete_404.py`):**
```python
def test_delete_unknown_session_returns_404():
    client = TestClient(_app(buggy=False))
    resp = client.delete("/v1/sessions/does-not-exist-000")
    assert resp.status_code == 404
    assert "not found" in resp.json()["detail"].lower()

def test_get_cancel_delete_agree_on_unknown_session():
    """Consistency contract: all three verbs 404 for the same unknown id."""
    client = TestClient(_app(buggy=False))
    unknown = "ghost-session-42"
    assert client.get(f"/v1/sessions/{unknown}").status_code == 404
    assert client.post(f"/v1/sessions/{unknown}/cancel").status_code == 404
    assert client.delete(f"/v1/sessions/{unknown}").status_code == 404
```

